  cond_.wait(lk, boost::bind(&sync_deque_base<ValueType, Queue>::not_empty_or_closed, boost::ref(*this), boost::ref(lk)));
  if (! empty(lk)) return false; // success
  return true; // closed

template <class ValueType, class Queue>
